#include "engine_effects.hpp"
#include <sstream>
namespace ofo {
EffectParameters load_effect_parameters(const Resources&r){EffectParameters p;if(!r.exists("particle/effectparams.txt"))return p;std::istringstream input(r.text("particle/effectparams.txt"));std::string line;while(std::getline(input,line)){std::istringstream row(line);std::string type,name;if(!(row>>type>>name))continue;std::vector<float>values;float f;while(row>>f){if(!std::isfinite(f))throw std::runtime_error("Nonfinite effect parameter: "+name);values.push_back(f);}auto one=[&](float&out){if(values.size()!=1)throw std::runtime_error("Invalid effect parameter: "+name);out=values[0];};auto two=[&](std::array<float,2>&out){if(values.size()!=2)throw std::runtime_error("Invalid effect range: "+name);out={values[0],values[1]};};
 if(name=="FireStart")one(p.fire_start);else if(name=="FireRadius")one(p.fire_radius);else if(name=="FireAlpha")one(p.fire_alpha);else if(name=="FireGrow")one(p.fire_grow);else if(name=="FireLifePower")one(p.fire_life_power);else if(name=="FireIterations"){float n=0;one(n);if(n<1||n>100)throw std::runtime_error("Invalid fire iterations");p.fire_iterations=int(n);}else if(name=="FireOffset"){if(values.size()!=3)throw std::runtime_error("Invalid FireOffset");p.fire_offset={values[0],values[1],values[2]};}else if(name=="FireSizePerRadius")two(p.fire_size);else if(name=="FireVelocityY")two(p.fire_velocity);else if(name=="FireLife")two(p.fire_life);else if(name=="FireAngleSpeed")two(p.fire_rotation);
 }if(p.fire_start<=0||p.fire_start>1||p.fire_radius<=0||p.fire_radius>10||p.fire_life[0]<=0||p.fire_life[1]<p.fire_life[0]||p.fire_life[1]>30||p.fire_life_power<0||p.fire_alpha<0||p.fire_size[0]<=0||p.fire_size[1]<p.fire_size[0])throw std::runtime_error("Invalid native engine effect limits");p.loaded=true;return p;}
int engine_damage_stage(float d,const EffectParameters&p){if(!std::isfinite(d))return 0;return d>=p.fire_start?3:d>=.5f?2:d>=.25f?1:0;}
EngineEffectVertices engine_effect_vertices(const EffectParameters&p,float damage,Vec origin,Vec velocity,Vec right,Vec up,double clock,bool menu){
 EngineEffectVertices out;engine_effect_vertices(p,damage,origin,velocity,right,up,clock,out,menu);return out;
}
void engine_effect_vertices(const EffectParameters&p,float damage,Vec origin,Vec velocity,Vec right,Vec up,double clock,EngineEffectVertices&out,bool menu,int detail_stride){
 out.smoke.clear();out.fire.clear();detail_stride=std::clamp(detail_stride,1,4);int stage=menu?1:engine_damage_stage(damage,p);if(!stage||!std::isfinite(clock))return;clock=std::max(0.,clock);right=unit(right,{1,0,0});up=unit(up);out.smoke.reserve(6*((40+detail_stride-1)/detail_stride));out.fire.reserve(6*((96+detail_stride-1)/detail_stride));
 auto quad=[&](std::vector<Vertex>&batch,Vec center,float size,float angle,uint32_t color,int x,int y,int w,int h){auto rx=right*std::cos(angle)+up*std::sin(angle),uy=up*std::cos(angle)-right*std::sin(angle);Vertex q[4];for(int k=0;k<4;k++){q[k].position=center+rx*((k==0||k==3?-1:1)*size)+uy*((k<2?1:-1)*size);q[k].normal={0,1,0};q[k].color=color;q[k].u=(x+(k==0||k==3?.5f:w-.5f))/512;q[k].v=(y+(k<2?.5f:h-.5f))/512;}for(int k:{0,1,2,0,2,3})batch.push_back(q[k]);};
 // Smoke cadence/thresholds are adapter values; the sprite cells are original.
 int smoke_count=menu?8:stage==1?5:10;for(int i=0;i<smoke_count;i+=detail_stride){float age=float(std::fmod(clock+i*3./smoke_count,3.)),t=age/3;Vec center=origin-velocity*(age*.3f)+Vec{std::sin(i*2.4f+age)*age*.12f,age*.8f,std::cos(i*1.7f)*age*.1f};float alpha=(menu?.10f:stage==1?.065f:.11f)*std::sin(t*3.14159265f);uint32_t color=(uint32_t(std::clamp(alpha,0.f,1.f)*255)<<24)|0xffffff;int x=(stage>=2?128:256)+(i%2)*64,y=(stage>=2?384:256)+((i/2)%2)*64;quad(out.smoke,center,.16f+age*(stage>=2?.45f:.3f),i*.7f+age*.15f,color,x,y,64,64);}
 if(stage==3){int count=std::clamp(p.fire_iterations*24,12,96);for(int i=0;i<count;i+=detail_stride){float random=float((i*37)%101)/100,life=p.fire_life[0]+random*(p.fire_life[1]-p.fire_life[0]);float age=float(std::fmod(clock+i*life/count,life)),t=age/life,phi=i*2.399963f;float speed=p.fire_velocity[0]+random*(p.fire_velocity[1]-p.fire_velocity[0]);Vec center=origin-velocity*(age*.15f)+Vec{std::cos(phi)*p.fire_radius,speed*age,std::sin(phi)*p.fire_radius};float size=p.fire_radius*(p.fire_size[0]+random*(p.fire_size[1]-p.fire_size[0]))*std::max(.01f,1+p.fire_grow*t);float alpha=.48f*p.fire_alpha*std::pow(1-t,p.fire_life_power);float angle=(p.fire_rotation[0]+random*(p.fire_rotation[1]-p.fire_rotation[0]))*age*.0174532925f;quad(out.fire,center,size,angle,(uint32_t(std::clamp(alpha,0.f,1.f)*255)<<24)|0xffffff,384,256,128,128);}}
}
}
